static canRender(options, viewportData, lineNumber) {
        const data = viewportData.getViewLineRenderingData(lineNumber);
        if (data.containsRTL ||
            data.maxColumn > 200 ||
            data.continuesWithWrappedLine ||
            data.inlineDecorations.length > 0) {
            return false;
        }
        return true;
    }
